        group post by post.BlogId into blogGroup
        select new { BlogId = blogGroup.Key, TotalViews = blogGroup.Sum(post => post.Views) };

    var totalViewsByBlog = await totalViewsQuery.ToListAsync(cancellationToken);
    return totalViewsByBlog.ToDictionary(total => total.BlogId, total => total.TotalViews);
}
